# F-12 / D1: the monthly INR price each plan may sell at. Free has none.
BANDS = {"startups": (900, 1000), "teams": (1799, 2000), "businesses": (2899, 3000)}


def seed_bands(apps, schema_editor):
    """Set the bands, and bring Businesses into its band: 28% off its list price (Rs 4,049 -> Rs 2,915)."""
    Plan = apps.get_model("z_auth", "Plan")
    for code, (low, high) in BANDS.items():
        Plan.objects.filter(code=code).update(band_min_inr=Decimal(low), band_max_inr=Decimal(high))
    plan = Plan.objects.filter(code="businesses").first()
    if plan is not None:
        plan.discount_percent = 28
        if plan.list_price_inr_monthly and plan.list_price_inr_monthly > 0:
            price = Decimal(plan.list_price_inr_monthly) * 72 / 100
            plan.price_inr_monthly = price.quantize(Decimal("1"), rounding=ROUND_HALF_UP).quantize(Decimal("0.01"))
        plan.save(update_fields=["discount_percent", "price_inr_monthly"])


def clear_bands(apps, schema_editor):
    apps.get_model("z_auth", "Plan").objects.update(band_min_inr=None, band_max_inr=None)



